webpackJsonp([0x9dae941c923f],{420:function(e,t){e.exports={data:{site:{siteMetadata:{title:"Mihail Eric",subtitle:"Engineer, researcher, educator.",copyright:"Copyright",author:{name:"Mihail Eric",twitter:"mihail_eric"},disqusShortname:"mihaileric",url:"https://mihaileric.com"}},allMarkdownRemark:{edges:[{node:{fields:{slug:"/posts/support-vector-machines/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Basics of Support Vector Machines",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-20T23:46:37.121"}}},{node:{fields:{slug:"/posts/not-so-naive-bayes/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why So Naive, Bayes?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-13T23:46:37.121"}}},{node:{fields:{slug:"/posts/introduction-to-logistic-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Introduction to Logistic Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamentals-of-linear-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Fundamentals of Linear Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-03-15T23:46:37.121"}}},{node:{fields:{slug:"/posts/transformers-attention-in-disguise/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Transformers: Attention in Disguise",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-22T23:46:37.121"}}},{node:{fields:{slug:"/posts/deep-contextualized-word-representations-elmo/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Deep Contextualized Word Representations with ELMo",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fast-object-detection-with-fast-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Fast Object Detection with Fast R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/object-detection-with-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Object Detection with R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamental-deep-learning-algorithms-to-learn/",tagSlugs:["/tags/a-i/","/tags/deep-learning/","/tags/machine-learning/"]},frontmatter:{title:"Fundamental Deep Learning Algorithms To Learn",tags:["A.I.","Deep Learning","Machine Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/why-all-the-excitement-about-ai/",tagSlugs:["/tags/a-i/","/tags/machine-learning/","/tags/deep-learning/"]},frontmatter:{title:"Why All The Excitement About Artificial Intelligence",tags:["A.I.","Machine Learning","Deep Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/being-a-good-machine-learning-data-scientist/",tagSlugs:["/tags/a-i/","/tags/data-science/","/tags/machine-learning/"]},frontmatter:{title:"Being a Good Machine Learning Engineer/Data Scientist",tags:["A.I.","Data Science","Machine Learning"],date:"2018-08-11T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-software-interview-challenge/",tagSlugs:["/tags/software-engineering/","/tags/interview-prep/"]},frontmatter:{title:"A Software Interview Challenge",tags:["Software Engineering","Interview Prep"],date:"2017-12-24T23:46:37.121"}}},{node:{fields:{slug:"/posts/review-of-sigdial-semdial-2017/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Review of SIGDial/SemDial 2017",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2017-09-04T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-new-multiturn-dialogue-dataset/",tagSlugs:["/tags/natural-language-processing/","/tags/dataset/","/tags/dialogue/"]},frontmatter:{title:"A New Multi-Turn, Multi-Domain, Task-Oriented Dialogue Dataset",tags:["Natural Language Processing","Dataset","Dialogue"],date:"2017-07-03T23:46:37.121"}}}]},markdownRemark:{id:"/Users/mihaileric/Documents/Projects/mihail911.github.io/src/pages/articles/2019-13-04---Naive-Bayes/index.md absPath of file >>> MarkdownRemark",html:'<figure>\n    \n  <a class="gatsby-resp-image-link" href="/static/naive_bayes_everywhere-66164a7cba08a24798ecf0c5b622994f-b6d5f.jpeg" style="display: block" target="_blank" rel="noopener">\n  \n  <span class="gatsby-resp-image-wrapper" style="position: relative; display: block; ; max-width: 500px; margin-left: auto; margin-right: auto;">\n    <span class="gatsby-resp-image-background-image" style="padding-bottom: 76.2%; position: relative; bottom: 0; left: 0; background-image: url(&apos;data:image/jpeg;base64,&apos;); background-size: cover; display: block;">\n      <img class="gatsby-resp-image-image" style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;" alt="naive bayes toy story" title="" src="/static/naive_bayes_everywhere-66164a7cba08a24798ecf0c5b622994f-b6d5f.jpeg" srcset="/static/naive_bayes_everywhere-66164a7cba08a24798ecf0c5b622994f-0f47f.jpeg 240w,\n/static/naive_bayes_everywhere-66164a7cba08a24798ecf0c5b622994f-696e5.jpeg 480w,\n/static/naive_bayes_everywhere-66164a7cba08a24798ecf0c5b622994f-b6d5f.jpeg 500w" sizes="(max-width: 500px) 100vw, 500px">\n    </span>\n  </span>\n  \n  </a>\n    \n    <figcaption>Source: Medium</figcaption>\n</figure>\n<View style={LessonStyles.separator} />\n        <Text style={LessonStyles.subHeading}>\n          In this lesson, we will explore a family of classification algorithms that has a very different theoretical\n          motivation from ones we\'ve seen previously. We will be looking at <Bold txt="support vector machines"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Back in the early 2000s\n          before deep learning surged to the forefront of AI, support vector machines were the cool kid on the block. Even today, support vector machines are still one of the best go-to algorithms\n          for a new classification task because of their powerful ability to\n          represent very diverse types of statistical relationships in data as well as their ease of training.\n        </Text>\n        <Text style={LessonStyles.subTitle}>\n          Max-Margin Motivations\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Let\'s begin by motivating support vector machines. Recall our ridiculously overused classification problem: identifying whether a car is <Bold txt="cheap"/> or <Bold txt="expensive"/>, based\n          on a set of features\n          of that car.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Imagine that we are plotting some of our data in 2-dimensional feature space. In other words, we are only\n          extracting two features, <Bold txt="X1"/> and <Bold txt="X2"/>, from each car for building our model.  Furthermore, let\'s label each point <Blue txt="BLUE"/> if it represents a car that is <Bold txt="cheap"/> and <Red txt="RED"/> if\n          it represents a car that is labelled <Bold txt="expensive"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          We will try to\n          learn a linear model of our features, parameterized by the weights <Bold txt="W1"/> and <Bold txt="W2"/>. Our model will output <Blue txt="BLUE"/> if <Bold txt="W1*X1 + W2*X2 < 0"/> and <Red txt="RED"/> if <Bold txt="W1*X1 + W2*X2 >= 0"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          This model will describe a linear separator of a collection of data. That linear separator of our data could look as follows:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 250}]} source={require(\'../../assets/linearSeparator1.png\')} />\n        <Text style={LessonStyles.subHeading}>\n          Here the datapoints above the line are classified as <Red txt="RED"/>, while those below are classified as <Blue txt="BLUE"/>. The important thing to see is that this is <Ital txt="only one"/> possible linear separator of the data.\n          However, we could envision another separator that could separate the dataset into two colored halves just as well:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 250}]} source={require(\'../../assets/linearSeparator2.png\')} />\n        <Text style={LessonStyles.subHeading}>\n          In fact, there are an <Ital txt="infinite"/> number of possible separators that would split the data perfectly! How do we choose among them?\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Consider how we decided to label a datapoint as <Red txt="RED"/> or <Blue txt="BLUE"/>. We computed <Bold txt="W1*X1 + W2*X2"/> and said if it was negative, we labelled the point <Blue txt="BLUE"/>. Otherwise\n          we labelled it <Red txt="RED"/>. Intuitively, it seems that if the quantity <Bold txt="W1*X1 + W2*X2"/> for a given point is 15, we are more confident that it should\n          be <Red txt="RED"/> than one for which the quantity is 1.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Alternatively, the more negative the quantity is for a point the more confident we are that it should be <Blue txt="BLUE"/>. In fact, we can use this value to\n          judge our confidence for every single point!\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Geometrically, this confidence for a point\'s label can be represented as the perpendicular distance from the point to the separator. Below we have designated the perpendicular distances\n          to the separator for several sample points with the <Green txt="GREEN"/> lines:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 200}]} source={require(\'../../assets/linearSeparatorWithDistance.png\')} />\n        <Text style={LessonStyles.subHeading}>\n          Now imagine if we took the minimum distance to the separator across all the points in the dataset. This minimum value is called the <Bold txt="margin"/>. Below we show the point that achieves the margin for the given separator:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 200}]} source={require(\'../../assets/marginDiagram.png\')} />\n        <Text style={LessonStyles.subHeading}>\n          Optimal margins are at the core of support vector machine theory, and they inform how we will pick the "best" linear separator among the infinite choices. The way we will do this is by picking the linear separator\n          that <Bold txt="maximizes the margin"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Put another way, each separator defines a certain margin (i.e. an associated minimum perpendicular distance\n          to the separator). Then, among the infinite possible separators, we will pick the separator that maximizes the margin.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Make sure you really understand that last statement!\n          Support vector machines are often called <Bold txt="max-margin classifiers"/> for that exact reason. Given an optimal margin linear separator, the points with the smallest margins that are closest to the\n          linear separator are called the <Bold txt="support vectors"/>.\n        </Text>\n        <Text style={LessonStyles.subTitle}>\n          Training the SVM\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          So, how do we train a support vector machine? The full mathematical details to describe the cost function we want to optimize are a bit beyond the scope of this lesson, but we will\n          give a brief description of the training cost function.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Given a collection of datapoints <Bold txt="[(X1, Y1), (X2, Y2), ... , (Xn, Yn)]"/> (where <Bold txt="X"/> are the input features\n          and <Bold txt="Y"/> are the correct output labels) and a vector of weights <Bold txt="W"/> for our input\n          features, finding the optimal margin classifier amounts to solving:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 120}]} source={require(\'../../assets/svmObjectiveDiagram.png\')} />\n        <Text style={LessonStyles.subHeading}>\n          This cost function is basically a fancy way of saying that we want maximize the margin, while ensuring the margin of each datapoint is greater than or equal to 1.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          It turns out finding the optimum for this cost function is a convex optimization problem, which means there exist standard algorithms for solving the problem. This is good news\n          for us because it means optimally training a support vector machine is a tractable problem!\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          As a point of comparison, there exist some problems for\n          which we cannot find the optimal value in a computationally reasonable time. It may even take exponential time to find the optimum!\n        </Text>\n        <Text style={LessonStyles.subTitle}>\n          The Kernel Trick\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Thus far we have motivated support vector machines by only focusing on linear separators of data.\n          It turns out that support vector machines can actually learn nonlinear separators, which is why they are such a powerful model class!\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          To motivate this idea,\n          imagine that we have an input point with three features <Bold txt="X = (X1, X2, X3)"/>. We can transform the 3-dimensional vector <Bold txt="X"/> into a higher-dimensional\n          vector by applying a transformation function as follows: <Bold txt="T(X) = (X1, X2, X3, X1*X1, X2*X2, X3*X3)"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Our transformation function did two things:\n          1) it created a 6-dimensional vector from a 3-dimensional one and 2) it added nonlinear interactions in our features by having certain new features be the squares\n          of the original features.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Transforming features into a higher-dimensional space has some perks, namely that some data which is not linearly separable in a certain-dimensional space could become\n          linearly separable when we project it into the higher-dimensional space.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          As a motivating example, consider the following data which is not linearly separable in 2-d space:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 200}]} source={require(\'../../assets/kernelTrickNotSeparableDiagram.png\')}/>\n        <Text style={LessonStyles.subHeading}>\n          which becomes separable in 3-dimensional space through an appropriate feature transformation:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 200}]} source={require(\'../../assets/kernelTrickSeparableDiagram.png\')}/>\n        <Text style={LessonStyles.subHeading}>\n          Such input feature transformations are particularly useful in support vector machines. It turns out that support vector machines formalize the notion of these feature transformation function through something called a <Bold txt="kernel"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Without getting too much into the mathematical details, a kernel allows a support vector machine to learn using these transformed features in higher-dimensional space in a much more computationally\n          efficient way. This is called the <Bold txt="kernel trick"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Examples of kernels that are frequently used when learning a support vector machine\n          model include the <Bold txt="polynomial kernel"/> and the <Bold txt="radial basis function kernel"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          A really crazy mathematical property of the radial\n          basis function is that it can be interpreted as a mapping for an infinite-dimensional feature space! And yet we can still use it to do effective learning\n          in our models. That\'s insane!\n        </Text>\n        <Text style={LessonStyles.subTitle}>\n          Slacking Off\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          Thus far, we have assumed that the data we are working with is always linearly separable. And if it wasn\'t to begin with, we assumed we could project it into a higher-dimensional feature space where\n          it would be linearly separable and the\n          kernel trick would do all the heavy lifting.\n        </Text>\n        <Text style={LessonStyles.subHeading}>\n          However, our data may not always be linearly separable. We may find ourselves in a situation as follows where it is impossible to linearly separate the data:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 200}]} source={require(\'../../assets/nonlinearlySeparableDiagram.png\')} />\n        <Text style={LessonStyles.subHeading} >\n          Moreover, recall that our original support vector machine cost function enforced the constraint that every point needs to have a margin greater than or equal to 1.\n        </Text>\n        <Text style={LessonStyles.subHeading} >\n          But perhaps this condition is too strict for all cases. For example, enforcing this condition for all points may make our model very susceptible to outliers as follows:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 200}]} source={require(\'../../assets/svmOutlierDiagram.png\')} />\n        <Text style={LessonStyles.subHeading} >\n          To combat this problem, we can introduce what are called <Bold txt="slack penalties"/> into our support vector machine objective that allow certain points to have margins potentially smaller\n          than 1. WIth these penalties, our new cost looks as follows:\n        </Text>\n        <Image style={[LessonStyles.image, {height: 130}]} source={require(\'../../assets/svmSlackObjectiveDiagram.png\')} />\n        <Text style={LessonStyles.subHeading} >\n          Here the <Bold txt="si"/> are our slack variables. Notice that we have changed the expression we are trying to minimize. The value <Bold txt="K"/> is\n          what is called a <Ital txt="hyperparameter"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading} >\n          In a nutshell, this means we can adjust <Bold txt="K"/> to determine how much we want our model to focus on minimizing the new term in our cost function or the old term.\n          This is our first example of a very important concept in machine learning called <Bold txt="regularization"/>.\n        </Text>\n        <Text style={LessonStyles.subHeading} >\n          We will discuss regularization in a lot more detail in the next section. For now, just understand that this new addition makes the support vector machine\n          more robust to nonlinearly-separable data.\n        </Text>\n        <Text style={LessonStyles.subTitle} >\n          Final Thoughts\n        </Text>\n        <Text style={LessonStyles.subHeading} >\n          Support vector machines are very powerful model. They are great for handling linearly separable data and with their various extensions\n          can adequately handle nonlinearly separable data scenarios.\n        </Text>\n        <Text style={LessonStyles.subHeading} >\n          As part of the machine learning toolkit, it is a great go-to model to try when\n          starting on a new problem. However, one of its downsides is that using certain kernels, such as the radial basis function kernel, can sometimes make the model\n          training slower, so be wary of that.\n        </Text>',fields:{tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why So Naive, Bayes?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-13T23:46:37.121",description:"I describe Naive Bayes, a commonly-used generative model for a variety of classification tasks."}}},pathContext:{slug:"/posts/not-so-naive-bayes/"}}}});
//# sourceMappingURL=path---posts-not-so-naive-bayes-53e7bc9109b1004be4b3.js.map